import { TableDataType, TableHeaderType } from 'components/Table/types';
import { FilterValue } from 'models/Filters';

const filterHeaderColumns = (
  header: TableHeaderType[],
  hiddenFields: Set<FilterValue>,
): TableHeaderType[] => {
  return header
    .map((column) => {
      if (column.children?.length) {
        const children = filterHeaderColumns(column.children, hiddenFields);

        if (children.length === 0) {
          return null;
        }

        return { ...column, children };
      }

      if (column.id && hiddenFields.has(column.id)) {
        return null;
      }

      return column;
    })
    .filter((column): column is TableHeaderType => column !== null);
};

export const filterTableDataByHiddenFields = (
  data: TableDataType,
  hiddenFields: FilterValue[],
): TableDataType => {
  if (!data.header?.length || hiddenFields.length === 0) {
    return data;
  }

  const hiddenFieldSet = new Set(hiddenFields);

  return {
    ...data,
    header: filterHeaderColumns(data.header, hiddenFieldSet),
  };
};
